22	const BIOME_DATA = [
23	  { name: 'ocean', temp: 0.5, humid: 0.5, water: '#3f76e4' },
24	  { name: 'plains', temp: 0.8, humid: 0.4, water: '#3f76e4' },
25	  { name: 'forest', temp: 0.7, humid: 0.8, water: '#3f76e4' },
26	  { name: 'birch_forest', temp: 0.6, humid: 0.6, water: '#3f76e4' },
27	  { name: 'taiga', temp: 0.25, humid: 0.8, water: '#287082' },
28	  { name: 'desert', temp: 2.0, humid: 0.0, water: '#32a598' },
29	  { name: 'savanna', temp: 1.2, humid: 0.0, water: '#2c8b9c' },
30	  { name: 'snowy_plains', temp: 0.0, humid: 0.5, water: '#3938c9' },
31	  { name: 'beach', temp: 0.8, humid: 0.4, water: '#3f76e4' },
32	  { name: 'mountains', temp: 0.2, humid: 0.3, water: '#3f76e4' },
33	  { name: 'frozen_ocean', temp: 0.0, humid: 0.5, water: '#3938c9' },
34	  { name: 'swamp', temp: 0.8, humid: 0.9, water: '#617b64' },
35	];
