37	function hash2i(x: number, z: number, seed: number): number {
38	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(z | 0, 668265263);
39	  h = Math.imul(h ^ (h >>> 13), 1274126177);
40	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
41	}
42	
43	function hash3i(x: number, y: number, z: number, seed: number): number {
44	  let h = seed ^ Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 1103515245) ^ Math.imul(z | 0, 668265263);
45	  h = Math.imul(h ^ (h >>> 13), 1274126177);
46	  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
47	}
48	
49	function valueNoise2(x: number, z: number, seed: number): number {
50	  const xi = Math.floor(x), zi = Math.floor(z);
51	  const xf = x - xi, zf = z - zi;
52	  const u = xf * xf * (3 - 2 * xf);
53	  const v = zf * zf * (3 - 2 * zf);
54	  const a = hash2i(xi, zi, seed), b = hash2i(xi + 1, zi, seed);
55	  const c = hash2i(xi, zi + 1, seed), d = hash2i(xi + 1, zi + 1, seed);
56	  const ab = a + (b - a) * u, cd = c + (d - c) * u;
57	  return ab + (cd - ab) * v;
58	}
59	
60	function fbm2(x: number, z: number, octaves: number, seed: number): number {
61	  let sum = 0, amp = 0.5, norm = 0, fx = x, fz = z;
62	  for (let i = 0; i < octaves; i++) {
63	    sum += valueNoise2(fx, fz, seed + i * 1013) * amp;
64	    norm += amp;
65	    amp *= 0.5;
66	    fx *= 2.03; fz *= 2.03;
67	  }
68	  return sum / norm;
69	}
