71	export interface Chunk {
72	  cx: number;
73	  cz: number;
74	  blocks: Uint16Array;
75	  light: Uint8Array;
76	  biomes: Uint8Array;
77	  heights: Int16Array;
78	  generated: boolean;
79	}
