81	class IntQueue {
82	  data: Int32Array;
83	  head = 0;
84	  tail = 0;
85	  constructor(capacity = 1 << 20) { this.data = new Int32Array(capacity); }
86	  get length() { return this.tail - this.head; }
87	  clear() { this.head = this.tail = 0; }
88	  push(v: number) {
89	    if (this.tail === this.data.length) {
90	      if (this.head > this.data.length / 2) {
91	        this.data.copyWithin(0, this.head, this.tail);
92	        this.tail -= this.head;
93	        this.head = 0;
94	      } else {
95	        const grown = new Int32Array(this.data.length * 2);
96	        grown.set(this.data);
97	        this.data = grown;
98	      }
99	    }
100	    this.data[this.tail++] = v;
101	  }
102	  pop(): number { return this.data[this.head++]; }
103	}
