105	export class World {
106	  readonly chunks = new Map<string, Chunk>();
107	  readonly grid: (Chunk | null)[];
108	  readonly gridSize: number;
109	  readonly originCX: number;
110	  readonly originCZ: number;
111	  readonly minWorldX: number;
112	  readonly minWorldZ: number;
113	  readonly maxWorldX: number;
114	  readonly maxWorldZ: number;
115	  readonly seed: number;
116	  readonly rocks: BlockRegistry;
117	
118	  readonly grassTint: Float32Array;
119	  readonly foliageTint: Float32Array;
120	  readonly waterTint: Float32Array;
121	
122	  private ids: Record<string, number> = {};
123	  private skyQueue = new IntQueue(1 << 21);
124	  private blockQueue = new IntQueue(1 << 16);
125	
126	  constructor(rocks: BlockRegistry, assets: LoadedAssets, seed = 0x26_02_2026) {
127	    this.rocks = rocks;
128	    this.seed = seed;
129	    this.gridSize = REGION_RADIUS * 2 + 1;
130	    this.originCX = -REGION_RADIUS;
131	    this.originCZ = -REGION_RADIUS;
132	    this.minWorldX = this.originCX * CHUNK_SIZE;
133	    this.minWorldZ = this.originCZ * CHUNK_SIZE;
134	    this.maxWorldX = (this.originCX + this.gridSize) * CHUNK_SIZE - 1;
135	    this.maxWorldZ = (this.originCZ + this.gridSize) * CHUNK_SIZE - 1;
136	    this.grid = new Array(this.gridSize * this.gridSize).fill(null);
137	
138	    this.grassTint = new Float32Array(BIOME_DATA.length * 3);
139	    this.foliageTint = new Float32Array(BIOME_DATA.length * 3);
140	    this.waterTint = new Float32Array(BIOME_DATA.length * 3);
141	    for (let i = 0; i < BIOME_DATA.length; i++) {
142	      const b = BIOME_DATA[i];
143	      const g = sampleColormap(assets.grassColormap, Math.min(1, b.temp), Math.min(1, b.humid));
144	      const f = sampleColormap(assets.foliageColormap, Math.min(1, b.temp), Math.min(1, b.humid));
145	      this.grassTint.set(g, i * 3);
146	      this.foliageTint.set(f, i * 3);
147	      const n = parseInt(b.water.slice(1), 16);
148	      this.waterTint[i * 3] = ((n >> 16) & 255) / 255;
149	      this.waterTint[i * 3 + 1] = ((n >> 8) & 255) / 255;
150	      this.waterTint[i * 3 + 2] = (n & 255) / 255;
151	    }
152	
153	    for (const name of [
154	      'stone', 'dirt', 'grass_block', 'sand', 'red_sand', 'gravel', 'clay', 'water', 'lava', 'ice', 'snow',
155	      'snow_block', 'oak_log', 'oak_leaves', 'birch_log', 'birch_leaves', 'spruce_log', 'spruce_leaves',
156	      'cactus', 'short_grass', 'fern', 'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy', 'allium',
157	      'lily_of_the_valley', 'dead_bush', 'coal_ore', 'iron_ore', 'copper_ore', 'diamond_ore', 'emerald_ore',
158	      'deepslate', 'bedrock', 'sandstone', 'red_sandstone', 'sulfur', 'sulfur_bricks', 'polished_sulfur', 'chiseled_sulfur',
159	      'cinnabar', 'cinnabar_bricks', 'polished_cinnabar', 'chiseled_cinnabar', 'sulfur_spike', 'moss_block',
160	    ]) {
161	      this.ids[name] = rocks.id(name);
162	    }
163	  }
164	
165	  chunkIndex(cx: number, cz: number): number {
166	    return (cx - this.originCX) * this.gridSize + (cz - this.originCZ);
167	  }
168	
169	  chunkAt(cx: number, cz: number): Chunk | null {
170	    if (cx < this.originCX || cz < this.originCZ) return null;
171	    if (cx >= this.originCX + this.gridSize || cz >= this.originCZ + this.gridSize) return null;
172	    return this.grid[this.chunkIndex(cx, cz)];
173	  }
174	
175	  createChunk(cx: number, cz: number): Chunk {
176	    const chunk: Chunk = {
177	      cx, cz,
178	      blocks: new Uint16Array(CHUNK_SIZE * CHUNK_SIZE * WORLD_HEIGHT),
179	      light: new Uint8Array(CHUNK_SIZE * CHUNK_SIZE * WORLD_HEIGHT),
180	      biomes: new Uint8Array(CHUNK_SIZE * CHUNK_SIZE),
181	      heights: new Int16Array(CHUNK_SIZE * CHUNK_SIZE).fill(SEA_LEVEL),
182	      generated: false,
183	    };
184	    this.chunks.set(`${cx},${cz}`, chunk);
185	    this.grid[this.chunkIndex(cx, cz)] = chunk;
186	    return chunk;
187	  }
188	
189	  idx(x: number, y: number, z: number): number {
190	    const lx = x & 15, lz = z & 15;
191	    return ((y - WORLD_MIN_Y) << 8) | (lz << 4) | lx;
192	  }
193	
194	  getBlock(x: number, y: number, z: number): number {
195	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return 0;
196	    const cx = x >> 4, cz = z >> 4;
197	    const c = this.chunkAt(cx, cz);
198	    if (!c) return 0;
199	    return c.blocks[this.idx(x, y, z)];
200	  }
201	
202	  setBlock(x: number, y: number, z: number, id: number): void {
203	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return;
204	    const c = this.chunkAt(x >> 4, z >> 4);
205	    if (!c) return;
206	    c.blocks[this.idx(x, y, z)] = id;
207	  }
208	
209	  getSky(x: number, y: number, z: number): number {
210	    if (y >= WORLD_MAX_Y) return 15;
211	    if (y < WORLD_MIN_Y) return 0;
212	    const c = this.chunkAt(x >> 4, z >> 4);
213	    if (!c) return 15;
214	    return c.light[this.idx(x, y, z)] >>> 4;
215	  }
216	
217	  getBlockLight(x: number, y: number, z: number): number {
218	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return 0;
219	    const c = this.chunkAt(x >> 4, z >> 4);
220	    if (!c) return 0;
221	    return c.light[this.idx(x, y, z)] & 15;
222	  }
223	
224	  setSky(x: number, y: number, z: number, v: number): void {
225	    const c = this.chunkAt(x >> 4, z >> 4);
226	    if (!c) return;
227	    const i = this.idx(x, y, z);
228	    c.light[i] = (c.light[i] & 15) | ((v & 15) << 4);
229	  }
230	
231	  setBlockLight(x: number, y: number, z: number, v: number): void {
232	    const c = this.chunkAt(x >> 4, z >> 4);
233	    if (!c) return;
234	    const i = this.idx(x, y, z);
235	    c.light[i] = (c.light[i] & 0xf0) | (v & 15);
236	  }
237	
238	  getBiome(x: number, z: number): number {
239	    const c = this.chunkAt(x >> 4, z >> 4);
240	    if (!c) return BIOME.plains;
241	    return c.biomes[(z & 15) * 16 + (x & 15)];
242	  }
243	
244	  biomeNameAt(x: number, z: number): string {
245	    return BIOME_DATA[this.getBiome(x, z)]?.name ?? 'plains';
246	  }
247	
248	  tintAt(x: number, z: number, mode: number, fixed: Float32Array | [number, number, number], ctx: 'vertex' | 'array' = 'array'): [number, number, number] {
249	    if (mode === 0) return [1, 1, 1];
250	    if (mode === 4) {
251	      return ctx === 'array' ? [fixed[0], fixed[1], fixed[2]] : [fixed[0], fixed[1], fixed[2]];
252	    }
253	    const b = this.getBiome(x, z) * 3;
254	    const arr = mode === 1 ? this.grassTint : mode === 2 ? this.foliageTint : this.waterTint;
255	    return [arr[b], arr[b + 1], arr[b + 2]];
256	  }
257	
258	  private heightAt(x: number, z: number): number {
259	    const cont = fbm2(x * 0.0016, z * 0.0016, 5, this.seed + 1);
260	    const hills = fbm2(x * 0.010, z * 0.010, 4, this.seed + 2);
261	    const detail = fbm2(x * 0.045, z * 0.045, 2, this.seed + 3);
262	    const ridgeN = fbm2(x * 0.0042, z * 0.0042, 3, this.seed + 4) * 2 - 1;
263	    const ridge = 1 - Math.abs(ridgeN);
264	    let h = 50 + cont * 46 + hills * 12 + detail * 2.5;
265	    if (cont > 0.66) h += (cont - 0.66) * 110 * ridge;
266	    const d2 = x * x + z * z;
267	    h += 9 * Math.exp(-d2 / (210 * 210));
268	    // A deterministic lake to the south-east gives the spawn a natural shore.
269	    const lakeNoise = (fbm2(x * 0.03, z * 0.03, 3, this.seed + 81) - 0.5) * 14;
270	    const lakeD = Math.hypot(x - 58, z + 42) + lakeNoise;
271	    const lake = 1 - smoothstep(26, 58, lakeD);
272	    h -= lake * 22;
273	    return Math.floor(h);
274	  }
275	
276	  private biomeAt(x: number, z: number, h: number): number {
277	    const t = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 11);
278	    const m = fbm2(x * 0.0022, z * 0.0022, 3, this.seed + 17);
279	    if (h < SEA_LEVEL - 2) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
280	    if (h <= SEA_LEVEL + 2) {
281	      if (h < SEA_LEVEL) return t < 0.24 ? BIOME.frozenOcean : BIOME.ocean;
282	      const shoreNoise = fbm2(x * 0.045, z * 0.045, 2, this.seed + 71);
283	      if (shoreNoise > 0.57) return t < 0.2 ? BIOME.snowy : BIOME.beach;
284	      if (t < 0.2) return BIOME.snowy;
285	      if (t > 0.74 && m < 0.42) return BIOME.desert;
286	      if (t < 0.32) return BIOME.taiga;
287	      if (m > 0.62) return BIOME.forest;
288	      return BIOME.plains;
289	    }
290	    if (h > 108) return BIOME.mountains;
291	    if (t < 0.2) return m > 0.5 ? BIOME.taiga : BIOME.snowy;
292	    if (t < 0.32) return BIOME.taiga;
293	    if (t > 0.74 && m < 0.42) return BIOME.desert;
294	    if (t > 0.66 && m < 0.55) return BIOME.savanna;
295	    if (m > 0.68 && h < SEA_LEVEL + 8 && t > 0.4) return BIOME.swamp;
296	    if (m > 0.62) return BIOME.forest;
297	    if (m > 0.5 && t < 0.62) return BIOME.birch;
298	    return BIOME.plains;
299	  }
300	
301	  private isTreeBiome(biome: number): boolean {
302	    return biome === BIOME.forest || biome === BIOME.birch || biome === BIOME.taiga ||
303	      biome === BIOME.plains || biome === BIOME.savanna || biome === BIOME.swamp;
304	  }
305	
306	  async generate(progress: (f: number, label: string) => void): Promise<void> {
307	    const total = this.gridSize * this.gridSize;
308	    let done = 0;
309	    for (let cx = this.originCX; cx < this.originCX + this.gridSize; cx++) {
310	      for (let cz = this.originCZ; cz < this.originCZ + this.gridSize; cz++) {
311	        this.generateChunk(cx, cz);
312	        done++;
313	        if (done % 8 === 0) {
314	          progress(0.72 + 0.14 * (done / total), `Generating terrain ${done}/${total}`);
315	          await new Promise(r => setTimeout(r, 0));
316	        }
317	      }
318	    }
319	    progress(0.87, 'Lighting the world');
320	    await new Promise(r => setTimeout(r, 0));
321	    this.computeLighting();
322	    progress(0.93, 'Placing features');
323	  }
324	
325	  private generateChunk(cx: number, cz: number): void {
326	    const c = this.createChunk(cx, cz);
327	    if (c.generated) return;
328	    c.generated = true;
329	    const baseX = cx * 16, baseZ = cz * 16;
330	    const { blocks, biomes, heights } = c;
331	    const ids = this.ids;
332	    for (let lz = 0; lz < 16; lz++) {
333	      for (let lx = 0; lx < 16; lx++) {
334	        const x = baseX + lx, z = baseZ + lz;
335	        const h = this.heightAt(x, z);
336	        const biome = this.biomeAt(x, z, h);
337	        const ci = lz * 16 + lx;
338	        biomes[ci] = biome;
339	        heights[ci] = h;
340	        const snowy = biome === BIOME.snowy || biome === BIOME.frozenOcean;
341	        const desert = biome === BIOME.desert;
342	        const beach = biome === BIOME.beach;
343	        const ocean = biome === BIOME.ocean || biome === BIOME.frozenOcean;
344	        const mountain = biome === BIOME.mountains;
345	
346	        let top = ids.grass_block;
347	        let filler = ids.dirt;
348	        if (desert) { top = ids.sand; filler = ids.sand; }
349	        else if (beach || ocean) { top = (h > 48 || h < 40) ? ids.sand : ids.gravel; filler = ids.sand; }
350	        else if (snowy) { top = h > 92 ? ids.snow_block : ids.snow_block; filler = ids.dirt; }
351	        else if (mountain) { top = h > 112 ? ids.snow_block : ids.stone; filler = ids.stone; }
352	        else if (biome === BIOME.swamp && h < SEA_LEVEL + 3) { top = ids.grass_block; filler = ids.dirt; }
353	
354	        const maxY = Math.max(h, SEA_LEVEL);
355	        for (let y = WORLD_MIN_Y; y <= maxY; y++) {
356	          if (y < WORLD_MIN_Y + 2 + ((hash3i(x, y, z, this.seed + 5) * 2) | 0)) {
357	            blocks[this.idx(x, y, z)] = ids.bedrock;
358	            continue;
359	          }
360	          if (y <= h) {
361	            let id = ids.stone;
362	            if (y < -8) id = ids.deepslate;
363	            if (y > h - 4) {
364	              if (y === h) id = top;
365	              else id = filler;
366	            }
367	            if (y < h - 4 && y < 0 && y > h - 30) {
368	              const r = hash3i(x, y, z, this.seed + 23);
369	              if (r < 0.012) id = ids.coal_ore;
370	              else if (r < 0.019) id = ids.iron_ore;
371	              else if (r < 0.023) id = ids.copper_ore;
372	              else if (r < 0.0242) id = ids.diamond_ore;
373	            }
374	            if (desert && y > h - 5) id = y === h ? ids.sand : ids.sandstone;
375	            blocks[this.idx(x, y, z)] = id;
376	          } else {
377	            let fluid = ids.water;
378	            if (snowy && y === SEA_LEVEL) fluid = ids.ice;
379	            blocks[this.idx(x, y, z)] = fluid;
380	          }
381	        }
382	        if (snowy && h >= SEA_LEVEL && h < 100) {
383	          const sy = h + 1;
384	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
385	        }
386	        if (mountain && h > 112) {
387	          const sy = h + 1;
388	          if (sy < WORLD_MAX_Y) blocks[this.idx(x, sy, z)] = ids.snow;
389	        }
390	      }
391	    }
392	
393	    // Trees and small plants. Kept away from chunk borders so canopies stay inside.
394	    const treeSpots: [number, number][] = [];
395	    for (let lz = 3; lz < 13; lz++) {
396	      for (let lx = 3; lx < 13; lx++) {
397	        const x = baseX + lx, z = baseZ + lz;
398	        const ci = lz * 16 + lx;
399	        const h = heights[ci];
400	        if (h < SEA_LEVEL) continue;
401	        const biome = biomes[ci];
402	        const ground = this.getBlock(x, h, z);
403	        if (ground !== ids.grass_block && ground !== ids.snow_block && ground !== ids.sand) continue;
404	        if (this.getBlock(x, h + 1, z) !== 0) continue;
405	        const rnd = hash2i(x, z, this.seed + 41);
406	        if (this.isTreeBiome(biome) && ground === ids.grass_block && rnd < this.treeChance(biome)) {
407	          if (treeSpots.some(([tx, tz]) => (tx - x) * (tx - x) + (tz - z) * (tz - z) < 12)) continue;
408	          treeSpots.push([x, z]);
409	          this.placeTree(c, x, h + 1, z, biome, hash2i(x, z, this.seed + 43));
410	          continue;
411	        }
412	        if (biome === BIOME.desert && ground === ids.sand && rnd < 0.018) {
413	          this.placeCactus(c, x, h + 1, z, hash2i(x, z, this.seed + 47));
414	          continue;
415	        }
416	        if (rnd < 0.08 && (ground === ids.grass_block || ground === ids.snow_block)) {
417	          let plant = ids.short_grass;
418	          const f = hash2i(x, z, this.seed + 53);
419	          if (f < 0.008) plant = [ids.poppy, ids.dandelion, ids.cornflower, ids.azure_bluet, ids.oxeye_daisy, ids.allium, ids.lily_of_the_valley][(f * 700) | 0] ?? ids.poppy;
420	          else if (biome === BIOME.taiga && f < 0.05) plant = ids.fern;
421	          this.setIfAir(c, x, h + 1, z, plant);
422	        }
423	      }
424	    }
425	
426	  }
427	
428	  private treeChance(biome: number): number {
429	    if (biome === BIOME.forest) return 0.035;
430	    if (biome === BIOME.birch) return 0.03;
431	    if (biome === BIOME.taiga) return 0.04;
432	    if (biome === BIOME.swamp) return 0.015;
433	    if (biome === BIOME.savanna) return 0.004;
434	    return 0.006;
435	  }
436	
437	  private setLocal(c: Chunk, x: number, y: number, z: number, id: number, overwrite = false): void {
438	    if (y < WORLD_MIN_Y || y >= WORLD_MAX_Y) return;
439	    const lx = x & 15, lz = z & 15;
440	    const i = this.idx(x, y, z);
441	    if (!overwrite && c.blocks[i] !== 0) return;
442	    c.blocks[i] = id;
443	  }
