449	  private placeTree(c: Chunk, x: number, y: number, z: number, biome: number, rnd: number): void {
450	    const ids = this.ids;
451	    let log = ids.oak_log, leaves = ids.oak_leaves, height = 5;
452	    if (biome === BIOME.birch) { log = ids.birch_log; leaves = ids.birch_leaves; height = 6; }
453	    else if (biome === BIOME.taiga) { log = ids.spruce_log; leaves = ids.spruce_leaves; height = 7; }
454	    height += (rnd * 3) | 0;
455	    if (this.getBlock(x, y + height, z) !== 0) return;
456	    for (let i = 0; i < height; i++) this.setLocal(c, x, y + i, z, log, true);
457	    if (biome === BIOME.taiga) {
458	      for (let ly = 2; ly <= height; ly++) {
459	        const r = ly % 2 === 0 ? 2 : 1;
460	        for (let dx = -r; dx <= r; dx++) {
461	          for (let dz = -r; dz <= r; dz++) {
462	            if (Math.abs(dx) === r && Math.abs(dz) === r) continue;
463	            this.setIfAir(c, x + dx, y + ly, z + dz, leaves);
464	          }
465	        }
466	      }
467	      this.setIfAir(c, x, y + height + 1, z, leaves);
468	    } else {
469	      const top = y + height - 1;
470	      for (let ly = top - 3; ly <= top + 1; ly++) {
471	        const r = (ly === top - 3 || ly === top + 1) ? 1 : 2;
472	        for (let dx = -r; dx <= r; dx++) {
473	          for (let dz = -r; dz <= r; dz++) {
474	            if (Math.abs(dx) === r && Math.abs(dz) === r) continue;
475	            if (r === 2 && Math.abs(dx) === 2 && Math.abs(dz) === 1 && hash3i(x + dx, ly, z + dz, this.seed + 61) < 0.3) continue;
476	            if (r === 2 && Math.abs(dx) === 1 && Math.abs(dz) === 2 && hash3i(x + dx, ly, z + dz, this.seed + 62) < 0.3) continue;
477	            if (dx === 0 && dz === 0 && ly <= top) continue;
478	            this.setIfAir(c, x + dx, ly, z + dz, leaves);
479	          }
480	        }
481	      }
482	    }
483	  }
