491	
492	  private pack(x: number, y: number, z: number): number {
493	    const lx = x - this.minWorldX;
494	    const lz = z - this.minWorldZ;
495	    const ly = y - WORLD_MIN_Y;
496	    return (lx & 511) | ((lz & 511) << Z_SHIFT) | ((ly & 511) << Y_SHIFT);
497	  }
498	  private unpackX(p: number) { return (p & 511) + this.minWorldX; }
499	  private unpackZ(p: number) { return ((p >> Z_SHIFT) & 511) + this.minWorldZ; }
500	  private unpackY(p: number) { return ((p >> Y_SHIFT) & 511) + WORLD_MIN_Y; }
501	
502	  private computeLighting(): void {
503	    // 1. Column skylight
504	    for (const c of this.chunks.values()) {
505	      const { blocks, light, heights } = c;
506	      for (let lz = 0; lz < 16; lz++) {
507	        for (let lx = 0; lx < 16; lx++) {
508	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
509	          let sky = 15;
510	          for (let y = WORLD_MAX_Y - 1; y >= WORLD_MIN_Y; y--) {
511	            const i = this.idx(x, y, z);
512	            const def = this.rocks.get(blocks[i]);
513	            if (def.flags && def.flags.opaque) {
514	              sky = 0;
515	              light[i] = 0;
516	              continue;
517	            }
518	            light[i] = (sky << 4) | (light[i] & 15);
519	            if (def.flags && def.flags.lightOpacity > 0) sky = Math.max(0, sky - def.flags.lightOpacity);
520	          }
521	        }
522	      }
523	    }
524	    // 2. Skylight flood fill near the surface
525	    this.skyQueue.clear();
526	    for (const c of this.chunks.values()) {
527	      for (let lz = 0; lz < 16; lz++) {
528	        for (let lx = 0; lx < 16; lx++) {
529	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
530	          const h = c.heights[lz * 16 + lx];
531	          const y0 = Math.max(WORLD_MIN_Y, Math.min(h, SEA_LEVEL) - 20);
532	          const y1 = Math.min(WORLD_MAX_Y - 1, Math.max(h, SEA_LEVEL) + 14);
533	          for (let y = y0; y <= y1; y++) {
534	            if ((c.light[this.idx(x, y, z)] >>> 4) > 0) this.skyQueue.push(this.pack(x, y, z));
535	          }
536	        }
537	      }
538	    }
539	    this.floodSky();
540	
541	    // 3. Block light
542	    this.blockQueue.clear();
543	    for (const c of this.chunks.values()) {
544	      for (let lz = 0; lz < 16; lz++) {
545	        for (let lx = 0; lx < 16; lx++) {
546	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
547	          for (let y = WORLD_MIN_Y; y < WORLD_MAX_Y; y++) {
548	            const i = this.idx(x, y, z);
549	            const em = this.rocks.emission[c.blocks[i]];
550	            if (em > 0) {
551	              c.light[i] = (c.light[i] & 0xf0) | em;
552	              this.blockQueue.push(this.pack(x, y, z));
553	            }
554	          }
555	        }
556	      }
557	    }
558	    this.floodBlock();
559	  }
