614	  relightAround(x: number, y: number, z: number, radius = 20): void {
615	    const x0 = Math.max(this.minWorldX, x - radius), x1 = Math.min(this.maxWorldX, x + radius);
616	    const z0 = Math.max(this.minWorldZ, z - radius), z1 = Math.min(this.maxWorldZ, z + radius);
617	    const y0 = Math.max(WORLD_MIN_Y, y - radius), y1 = Math.min(WORLD_MAX_Y - 1, y + radius);
618	    // Reset light in the box, then recompute skylight columns and flood from the box boundary and emitters.
619	    for (let zz = z0; zz <= z1; zz++) {
620	      for (let xx = x0; xx <= x1; xx++) {
621	        const c = this.chunkAt(xx >> 4, zz >> 4);
622	        if (!c) continue;
623	        for (let yy = y0; yy <= y1; yy++) {
624	          const i = this.idx(xx, yy, zz);
625	          c.light[i] = 0;
626	        }
627	      }
628	    }
629	    this.skyQueue.clear();
630	    this.blockQueue.clear();
631	    for (let zz = z0; zz <= z1; zz++) {
632	      for (let xx = x0; xx <= x1; xx++) {
633	        let sky = y1 + 1 < WORLD_MAX_Y ? this.getSky(xx, y1 + 1, zz) : 15;
634	        for (let yy = y1; yy >= y0; yy--) {
635	          const c = this.chunkAt(xx >> 4, zz >> 4);
636	          if (!c) break;
637	          const i = this.idx(xx, yy, zz);
638	          const def = this.rocks.get(c.blocks[i]);
639	          if (def.flags && def.flags.opaque) { sky = 0; continue; }
640	          c.light[i] = (sky << 4) | (c.light[i] & 15);
641	          if (def.flags && def.flags.lightOpacity > 0) sky = Math.max(0, sky - def.flags.lightOpacity);
642	          if (sky > 0) this.skyQueue.push(this.pack(xx, yy, zz));
643	        }
644	      }
645	    }
646	    // Boundary seeds from outside the box.
647	    for (let zz = z0; zz <= z1; zz++) {
648	      for (let yy = y0; yy <= y1; yy++) {
649	        for (const xx of [x0 - 1, x1 + 1]) {
650	          if (xx < this.minWorldX || xx > this.maxWorldX) continue;
651	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
652	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
653	        }
654	      }
655	    }
656	    for (let xx = x0; xx <= x1; xx++) {
657	      for (let yy = y0; yy <= y1; yy++) {
658	        for (const zz of [z0 - 1, z1 + 1]) {
659	          if (zz < this.minWorldZ || zz > this.maxWorldZ) continue;
660	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
661	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
662	        }
663	      }
664	    }
665	    for (let zz = z0; zz <= z1; zz++) {
666	      for (let xx = x0; xx <= x1; xx++) {
667	        for (const yy of [y0 - 1, y1 + 1]) {
668	          if (yy < WORLD_MIN_Y || yy >= WORLD_MAX_Y) continue;
669	          const s = this.getSky(xx, yy, zz); if (s > 0) this.skyQueue.push(this.pack(xx, yy, zz));
670	          const b = this.getBlockLight(xx, yy, zz); if (b > 0) this.blockQueue.push(this.pack(xx, yy, zz));
671	        }
672	      }
673	    }
674	    // Emitters inside the box.
675	    for (let zz = z0; zz <= z1; zz++) {
676	      for (let xx = x0; xx <= x1; xx++) {
677	        const c = this.chunkAt(xx >> 4, zz >> 4);
678	        if (!c) continue;
679	        for (let yy = y0; yy <= y1; yy++) {
680	          const em = this.rocks.emission[c.blocks[this.idx(xx, yy, zz)]];
681	          if (em > 0) {
682	            this.setBlockLight(xx, yy, zz, em);
683	            this.blockQueue.push(this.pack(xx, yy, zz));
684	          }
685	        }
686	      }
687	    }
688	    this.floodSkyBox(x0, x1, y0, y1, z0, z1);
689	    this.floodBlockBox(x0, x1, y0, y1, z0, z1);
690	  }
