741	  findSpawn(): { x: number, y: number, z: number, yaw: number } {
742	    const coast = this.findCoastSpawn();
743	    if (coast) return coast;
744	    let best: { x: number, y: number, z: number } | null = null;
745	    let bestScore = -1e9;
746	    for (let r = 0; r <= 88; r += 4) {
747	      const steps = r === 0 ? 1 : Math.min(72, Math.max(16, Math.round(r * 1.2)));
748	      for (let a = 0; a < steps; a++) {
749	        const ang = (a / steps) * Math.PI * 2;
750	        const x = Math.round(Math.cos(ang) * r);
751	        const z = Math.round(Math.sin(ang) * r);
752	        const c = this.chunkAt(x >> 4, z >> 4);
753	        if (!c) continue;
754	        const h = c.heights[(z & 15) * 16 + (x & 15)];
755	        const biome = this.getBiome(x, z);
756	        const minH = biome === BIOME.beach ? SEA_LEVEL : SEA_LEVEL + 2;
757	        if (h < minH || h > 132) continue;
758	        const top = this.getBlock(x, h, z);
759	        if (top !== this.ids.grass_block && top !== this.ids.sand) continue;
760	        if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.mountains) continue;
761	        let clear = true;
762	        for (let dy = 1; dy <= 5; dy++) if (this.getBlock(x, h + dy, z) !== 0) { clear = false; break; }
763	        if (!clear) continue;
764	        let trees = 0;
765	        for (let dz = -4; dz <= 4; dz++) {
766	          for (let dx = -4; dx <= 4; dx++) {
767	            for (let dy = 1; dy <= 14; dy++) {
768	              const id = this.getBlock(x + dx, h + dy, z + dz);
769	              if (id === this.ids.oak_leaves || id === this.ids.birch_leaves || id === this.ids.spruce_leaves) trees++;
770	            }
771	          }
772	        }
773	        if (trees > 24) continue;
774	        let water = 0;
775	        for (let k = 0; k < 16; k++) {
776	          const aa = (k / 16) * Math.PI * 2;
777	          for (let d = 8; d <= 40; d += 4) {
778	            if (this.getBlock(Math.round(x + Math.cos(aa) * d), SEA_LEVEL, Math.round(z + Math.sin(aa) * d)) === this.ids.water) water++;
779	          }
780	        }
781	        let open = 0;
782	        for (let k = 0; k < 8; k++) {
783	          const aa = (k / 8) * Math.PI * 2;
784	          const cc = this.chunkAt((x + Math.round(Math.cos(aa) * 24)) >> 4, (z + Math.round(Math.sin(aa) * 24)) >> 4);
785	          if (!cc) continue;
786	          const hh = cc.heights[((z + Math.round(Math.sin(aa) * 24)) & 15) * 16 + ((x + Math.round(Math.cos(aa) * 24)) & 15)];
787	          if (hh < h + 6) open++;
788	        }
789	        const biomeScore = biome === BIOME.beach ? 20 : biome === BIOME.plains ? 6.5 : biome === BIOME.savanna ? 4.5 : biome === BIOME.birch ? 1 : 0;
790	        const score = biomeScore + Math.min(7, water * 0.18) + open * 0.22 - trees * 0.12 - Math.abs(h - 70) * 0.035;
791	        if (score > bestScore) {
792	          bestScore = score;
793	          best = { x, y: h + 1, z };
794	        }
795	      }
796	    }
797	    if (!best) best = { x: 8, y: 100, z: 8 };
798	    for (let dz = -3; dz <= 3; dz++) {
799	      for (let dx = -3; dx <= 3; dx++) {
800	        for (let dy = 1; dy <= 12; dy++) {
801	          const id = this.getBlock(best.x + dx, best.y + dy, best.z + dz);
802	          if (id === this.ids.oak_leaves || id === this.ids.birch_leaves || id === this.ids.spruce_leaves ||
803	            id === this.ids.oak_log || id === this.ids.birch_log || id === this.ids.spruce_log) {
804	            this.setBlock(best.x + dx, best.y + dy, best.z + dz, 0);
805	          }
806	        }
807	      }
808	    }
809	    return { ...best, yaw: this.suggestYaw(best.x, best.z) };
810	  }
