818	  private findCoastSpawn(): { x: number, y: number, z: number, yaw: number } | null {
819	    const waters: [number, number][] = [];
820	    for (const c of this.chunks.values()) {
821	      for (let lz = 0; lz < 16; lz += 3) {
822	        for (let lx = 0; lx < 16; lx += 3) {
823	          const x = c.cx * 16 + lx, z = c.cz * 16 + lz;
824	          if (this.getBlock(x, SEA_LEVEL, z) === this.ids.water && this.getBlock(x, SEA_LEVEL + 1, z) === 0) {
825	            waters.push([x, z]);
826	          }
827	        }
828	      }
829	    }
830	    if (!waters.length) return null;
831	    let sumX = 0, sumZ = 0;
832	    for (const [wx, wz] of waters) { sumX += wx; sumZ += wz; }
833	    const waterCenterX = sumX / waters.length, waterCenterZ = sumZ / waters.length;
834	    type Coast = { x: number, z: number, y: number, yaw: number, score: number };
835	    let best: Coast | null = null;
836	    for (let wi = 0; wi < waters.length; wi += 5) {
837	      const [wx, wz] = waters[wi];
838	      for (let r = 6; r <= 26; r += 2) {
839	        const steps = Math.max(12, r * 2);
840	        for (let a = 0; a < steps; a++) {
841	          const ang = (a / steps) * Math.PI * 2;
842	          const x = Math.round(wx + Math.cos(ang) * r);
843	          const z = Math.round(wz + Math.sin(ang) * r);
844	          if (Math.abs(x) > 90 || Math.abs(z) > 90) continue;
845	          const c = this.chunkAt(x >> 4, z >> 4);
846	          if (!c) continue;
847	          const h = c.heights[(z & 15) * 16 + (x & 15)];
848	          if (h < SEA_LEVEL || h > SEA_LEVEL + 34) continue;
849	          const top = this.getBlock(x, h, z);
850	          if (top !== this.ids.grass_block && top !== this.ids.sand) continue;
851	          const biome = this.getBiome(x, z);
852	          if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.mountains) continue;
853	          let clear = true;
