let surfaceBlocks = 0;
const counts: Record<string, number> = {};
const interesting = ['short_grass', 'fern', 'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy', 'allium', 'lily_of_the_valley', 'dead_bush', 'oak_log', 'birch_log', 'spruce_log', 'oak_leaves', 'birch_leaves', 'spruce_leaves', 'stone', 'mossy_cobblestone'];
for (const n of interesting) counts[n] = 0;
for (const c of world.chunks.values()) {
  for (let lz = 0; lz < 16; lz++) {
