private heightAt(x: number, z: number): number {
  const cont = fbm2(x * 0.0016, z * 0.0016, 5, this.seed + 1);
  const hills = fbm2(x * 0.010, z * 0.010, 4, this.seed + 2);
  const detail = fbm2(x * 0.045, z * 0.045, 2, this.seed + 3);
  const ridgeN = fbm2(x * 0.0042, z * 0.0042, 3, this.seed + 4) * 2 - 1;
  const ridge = 1 - Math.abs(ridgeN);
  let h = 50 + cont * 46 + hills * 12 + detail * 2.5;
  if (cont > 0.66) h += (cont - 0.66) * 110 * ridge;
  const d2 = x * x + z * z;
  h += 9 * Math.exp(-d2 / (210 * 210));
  // A deterministic lake to the south-east gives the spawn a natural shore.
  const lakeNoise = (fbm2(x * 0.03, z * 0.03, 3, this.seed + 81) - 0.5) * 14;
  const lakeD = Math.hypot(x - 58, z + 42) + lakeNoise;
  const lake = 1 - smoothstep(26, 58, lakeD);
  h -= lake * 22;
  return Math.floor(h);
}

