        treeSpots.push([x, z]);
        this.placeTree(c, x, h + 1, z, biome, hash2i(x, z, this.seed + 43));
        continue;
      }
      if (biome === BIOME.desert && ground === ids.sand && rnd < 0.018) {
        this.placeCactus(c, x, h + 1, z, hash2i(x, z, this.seed + 47));
        continue;
      }
      if (rnd < 0.08 && (ground === ids.grass_block || ground === ids.snow_block)) {
        let plant = ids.short_grass;
        const f = hash2i(x, z, this.seed + 53);
