  if (ground === ids.sand || ground === ids.red_sand) {
    const deadChance = biome === BIOME.desert ? 0.006 : (lakeS > -18 ? 0.013 : 0);
    if (deadChance > 0 && hash2i(x, z, this.seed + 120) < deadChance) {
      this.setIfAir(c, x, h + 1, z, ids.dead_bush);
