  const ids = this.ids;
  let log = ids.oak_log, leaves = ids.oak_leaves, height = 5;
  if (biome === BIOME.birch) { log = ids.birch_log; leaves = ids.birch_leaves; height = 6; }
  else if (biome === BIOME.taiga) { log = ids.spruce_log; leaves = ids.spruce_leaves; height = 7; }
  height += (rnd * 3) | 0;
