      this.setBlock(chosen.x + dx, h + 1, chosen.z + dz, 0);
      n++;
    }
  }
  this.setBlock(chosen.x, chosen.hs[1][1] + 1, chosen.z, ids.sulfur_spike);
  this.setBlock(chosen.x + 1, chosen.hs[1][2] + 1, chosen.z, ids.sulfur_spike);
