import { readFileSync } from 'fs';
import { World, SEA_LEVEL } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/world.ts';
import { BlockRegistry } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/blocks.ts';

