const manifest = JSON.parse(readFileSync(root + '/public/mc/manifest.json', 'utf8'));
const rocks = new BlockRegistry(manifest);
const cm = { width: 1, height: 1, data: new Uint8ClampedArray([120, 160, 80, 255]) } as any;
const world = new World(rocks, { grassColormap: cm, foliageColormap: cm } as any, 0x2602c0de);
await world.generate(() => {});
const s = world.findSpawn();
world.decorateSpawn(s);

const hAt = (x: number, z: number) => { const c = world.chunkAt(x >> 4, z >> 4); return c ? c.heights[(z & 15) * 16 + (x & 15)] : -99; };
const ch = (x: number, z: number) => {
  const h = hAt(x, z);
  if (h < SEA_LEVEL) return '~';
  const top = rocks.get(world.getBlock(x, h, z)).name;
  if (top.startsWith('sand')) return '.';
  if (top.startsWith('gravel')) return ',';
  if (top.startsWith('clay')) return ':';
  if (top.startsWith('stone') || top.startsWith('mossy')) return 'R';
  if (top.startsWith('grass')) return h <= SEA_LEVEL + 2 ? '"' : '#';
  if (top.startsWith('snow')) return '*';
  return '?';
