world.decorateSpawn(spawn);
const name = (id: number) => rocks.get(id).name;
const hAt = (x: number, z: number) => { const c = world.chunkAt(x >> 4, z >> 4); return c ? c.heights[(z & 15) * 16 + (x & 15)] : -99; };
const dir = { x: -Math.sin(spawn.yaw), z: Math.cos(spawn.yaw) };
const angOf = (dx: number, dz: number) => Math.acos(Math.max(-1, Math.min(1, (dx * dir.x + dz * dir.z) / Math.hypot(dx, dz))));

let waterAbove = 0;
for (const c of world.chunks.values()) {
  for (let y = SEA_LEVEL + 1; y < SEA_LEVEL + 60; y++) {
    for (let lz = 0; lz < 16; lz++) for (let lx = 0; lx < 16; lx++) {
      if (world.getBlock(c.cx * 16 + lx, y, c.cz * 16 + lz) === rocks.id('water')) waterAbove++;
    }
  }
}

// Trees within 40 blocks: species, trunk height, canopy block count, angle.
const trees: any[] = [];
for (let z = spawn.z - 40; z <= spawn.z + 40; z++) {
  for (let x = spawn.x - 40; x <= spawn.x + 40; x++) {
    const h = hAt(x, z);
    if (h < SEA_LEVEL) continue;
    if (!name(world.getBlock(x, h + 1, z)).endsWith('_log')) continue;
    const log = name(world.getBlock(x, h + 1, z));
    let th = 0; while (name(world.getBlock(x, h + 1 + th, z)).endsWith('_log')) th++;
    let leaves = 0;
    for (let dy = 1; dy <= th + 5; dy++) for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) {
      if (name(world.getBlock(x + dx, h + dy, z + dz)).endsWith('_leaves')) leaves++;
    }
    trees.push({ x, z, log, th, leaves, dist: +Math.hypot(x - spawn.x, z - spawn.z).toFixed(1), ang: +(angOf(x - spawn.x, z - spawn.z) * 180 / Math.PI).toFixed(0) });
  }
}
trees.sort((a, b) => a.dist - b.dist);

let grass = 0, flowers = 0, ferns = 0, bushes = 0, boulders = 0;
const plantNames = new Set(['short_grass', 'fern', 'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy', 'allium', 'lily_of_the_valley', 'dead_bush']);
let corridorPlants = 0;
for (let dz = -18; dz <= 18; dz++) for (let dx = -18; dx <= 18; dx++) {
  const x = spawn.x + dx, z = spawn.z + dz;
  const h = hAt(x, z);
  const top = world.getBlock(x, h + 1, z);
  if (top === 0) {
    const solidTop = name(world.getBlock(x, h, z));
    if (solidTop === 'stone' || solidTop === 'mossy_cobblestone') boulders++;
