let area = 0, perim = 0, minX = 999, maxX = -999, minZ = 999, maxZ = -999;
const depths: number[] = [];
let maxStep = 0, step2 = 0, step3 = 0, landCount = 0;
for (let z = -90; z <= 60; z++) {
  for (let x = -60; x <= 110; x++) {
    if (!isWater(x, z)) continue;
    area++;
    minX = Math.min(minX, x); maxX = Math.max(maxX, x); minZ = Math.min(minZ, z); maxZ = Math.max(maxZ, z);
    depths.push(SEA_LEVEL - hAt(x, z));
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      if (!isWater(x + dx, z + dz)) perim++;
