import { readFileSync } from 'fs';
import { World, SEA_LEVEL } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/world.ts';
import { BlockRegistry } from 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26/src/blocks.ts';

const root = 'C:/Users/zht/Documents/Qoder/2026-11-01/4194ac07/webcraft26';
const manifest = JSON.parse(readFileSync(root + '/public/mc/manifest.json', 'utf8'));
const rocks = new BlockRegistry(manifest);
const cm = { width: 1, height: 1, data: new Uint8ClampedArray([120, 160, 80, 255]) } as any;
const world = new World(rocks, { grassColormap: cm, foliageColormap: cm } as any, 0x2602c0de);
await world.generate(() => {});
const spawn = world.findSpawn();
world.decorateSpawn(spawn);
const name = (id: number) => rocks.get(id).name;
const dir = { x: -Math.sin(spawn.yaw), z: Math.cos(spawn.yaw) };
let treeBlocks = 0, terrainBlocked = 0, waterCols = 0;
const samples: string[] = [];
for (let a = -0.35; a <= 0.35001; a += 0.05) {
  const ang = Math.atan2(dir.z, dir.x) + a;
  const fx = Math.cos(ang), fz = Math.sin(ang);
  let hitWater = false;
  for (let d = 2; d <= 40; d += 1) {
    const x = Math.round(spawn.x + fx * d), z = Math.round(spawn.z + fz * d);
    const c = world.chunkAt(x >> 4, z >> 4);
    if (!c) continue;
    const h = c.heights[(z & 15) * 16 + (x & 15)];
    if (h > spawn.y + 1 - d * 0.05) terrainBlocked++;
    for (let y = spawn.y + 1; y <= spawn.y + 8; y++) if (name(world.getBlock(x, y, z)).endsWith('_leaves') || name(world.getBlock(x, y, z)).endsWith('_log')) treeBlocks++;
    if (h < SEA_LEVEL) { waterCols++; hitWater = true; break; }
  }
  samples.push(`${(a * 180 / Math.PI).toFixed(0)}deg:${hitWater ? 'water' : 'land'}`);
}
console.log({ spawn, treeBlocks, terrainBlocked, waterCols, samples: samples.join(' ') });

